static int handle_invoke_action_with_token(sd_bus_message *msg, void *data,
		sd_bus_error *ret_error) {
	struct mako_state *state = data;

	uint32_t id = 0;
	const char *action_key, *token;
	int ret = sd_bus_message_read(msg, "uss", &id, &action_key, &token);
	if (ret < 0) {
		return ret;
	}

	// An empty token means the caller had none to give; fall back to minting.
	invoke_action(state, id, action_key, token[0] != '\\0' ? token : NULL);

	return sd_bus_reply_method_return(msg, "");
