"""// Read an activation token from stdin. Taken on stdin rather than as an
// argument because argv is readable by any same-uid process through
// /proc/<pid>/cmdline, and the token is a bearer credential.
static int read_token(char *buf, size_t size) {
	size_t len = 0;
	while (len + 1 < size) {
		ssize_t n = read(STDIN_FILENO, buf + len, size - len - 1);
		if (n < 0) {
			if (errno == EINTR) {
				continue;
			}
			return -errno;
		}
		if (n == 0) {
			break;
		}
		len += n;
	}
	buf[len] = '\\0';

	// Trim the trailing newline hyprctl and friends append.
	while (len > 0 && (buf[len - 1] == '\\n' || buf[len - 1] == '\\r')) {
		buf[--len] = '\\0';
	}

	return 0;
}

static int run_invoke(sd_bus *bus, int argc, char *argv[]) {
	uint32_t id = 0;
	bool token_stdin = false;
	static const struct option invoke_options[] = {
		{"token-stdin", no_argument, NULL, 't'},
		{0},
	};
	while (true) {
		int opt = getopt_long(argc, argv, "n:", invoke_options, NULL);
		if (opt == -1) {
			break;
		}

		switch (opt) {
		case 'n':;
			int ret = parse_uint32(&id, optarg);
			if (ret < 0) {
				log_neg_errno(ret, "invalid notification ID");
				return 1;
			}
			break;
		case 't':
			token_stdin = true;
			break;
		default:
			return -EINVAL;
		}
	}

	const char *action = "default";
	if (optind < argc) {
		action = argv[optind];
	}

	if (token_stdin) {
		char token[512];
		int ret = read_token(token, sizeof(token));
		if (ret < 0) {
			log_neg_errno(ret, "failed to read activation token from stdin");
			return 1;
		}
		return call_method(bus, "InvokeActionWithToken", NULL, "uss",
			id, action, token);
	}

	return call_method(bus, "InvokeAction", NULL, "us", id, action);
}""")

